"""Invariant unsigned division: basic and JIT advanced reciprocal paths."""
def register(topic, q, detail):
    def lesson(title, path, symbol, why, principle, use, reading, qa, cards):
        topic(title, '라이브러리·알고리즘', path, symbol,
              why, principle, use, reading, *(q(*x) for x in qa),
              details=[detail(*x) for x in cards])

    lesson('고정 제수 나눗셈·느린 준비와 빠른 반복 계산', 'lib/math/reciprocal_div.c', 'reciprocal_value',
        '제수가 자주 바뀌지 않을 때 나눗셈 준비 비용을 한 번 지불하고 반복 연산을 줄이는 방법을 배웁니다.',
        '양수 u32 제수 d에 대해 l=fls(d-1)은 ceil(log2(d))입니다. 준비 함수는 2^32*(2^l-d)를 d로 나누고 1을 더해 m을 만들며, sh1=min(l,1), sh2=max(l-1,0)을 저장합니다. 이 구조체를 반복 나눗셈에 재사용합니다. 준비에는 실제 나눗셈이 있으므로 제수마다 한 번만 계산하는 사용 흐름이 중요합니다.',
        '제수 0을 전달하지 않습니다. 제수가 바뀌면 새로운 구조체를 준비해야 합니다. 입력과 제수가 모두 u32인 부호 없는 정수 몫을 위한 방법이며 부동소수점 역수의 근삿값으로 결과를 추정하는 방식과 구분합니다.',
        'fls(d-1), u64 중간값, do_div와 두 shift 값을 읽으세요.',
        [('반복하는 제수가 바뀌었는데 이전 reciprocal_value를 재사용하면?', '새 제수의 정확한 몫을 보장할 수 없다', '모든 제수에 같은 구조체가 통한다', 'm과 두 이동량은 특정 d로부터 계산됩니다. 새 d에 맞게 다시 준비하지 않으면 다른 나눗셈을 수행합니다.'),
         ('d=8에서 fls(d-1)이 나타내는 값은?', '3이다', '8이다', 'd-1=7의 가장 높은 1비트까지의 길이는 3입니다. 이는 8을 만드는 2의 거듭제곱 지수와 같습니다.')],
        [('do_div 문맥', 'do_div는 64비트 피제수를 제수로 나눈 몫으로 갱신하는 커널 매크로입니다. 준비 함수에서 그 갱신 결과를 사용하며 일반 C 함수의 값 반환으로만 읽으면 계산을 놓칩니다.'),
         ('자료 구조', 'include/linux/reciprocal_div.h의 reciprocal_value는 u32 m과 u8 sh1·sh2를 저장합니다. 준비와 계산 API가 이 작은 문맥을 공유합니다.')])

    lesson('고정 제수 나눗셈·곱의 높은 절반과 몫 보정', 'include/linux/reciprocal_div.h', 'reciprocal_divide',
        '정수 곱셈과 이동만으로 정확한 부호 없는 나눗셈 몫을 구하는 계산 경로를 배웁니다.',
        't=((u64)a*R.m)>>32는 32비트 두 수의 곱에서 높은 32비트를 얻습니다. 결과는 (t+((a-t)>>sh1))>>sh2입니다. 준비 단계에서 만든 m과 이동량이 높은 곱의 값과 차이 보정을 결합해 floor(a/d)를 제공합니다. 먼저 u64로 확장해야 곱의 높은 절반이 잘리지 않습니다.',
        '같은 d로 준비한 R에 서로 다른 a를 전달합니다. u32 정수 나눗셈 a/d와 비교할 수 있으며 정수 몫만 반환하므로 나머지가 필요하면 별도로 계산합니다. 부호 있는 나눗셈의 음수 반올림 계약으로 확대하지 않습니다.',
        '곱셈 전에 적용되는 u64 cast와 보정의 괄호 순서를 읽으세요.',
        [('u64 cast를 곱셈 뒤로 옮기면 어떤 문제가 있는가?', '32비트 곱에서 이미 잘린 높은 비트를 복원할 수 없다', '곱셈 결과가 자동으로 언제나 더 정확해진다', '곱을 넓은 형식에서 계산해야 높은 절반을 얻습니다. 좁은 곱이 끝난 뒤 확장하면 잃어버린 정보를 되돌릴 수 없습니다.'),
         ('같은 준비 구조로 계산하는 7/3의 부호 없는 몫은?', '2다', '2.3333을 부동소수점으로 반환한다', '이 API는 정수 나눗셈 몫을 계산합니다. 준비와 곱·보정은 floor(7/3)=2를 만들어야 합니다.')],
        [('제수 1', 'l=0이면 sh1과 sh2가 0입니다. 준비된 경로는 a를 그대로 반환하며 제수 1도 별도의 입력 범위 안에 포함됩니다.'),
         ('검증 기준', '준비와 계산을 연결한 결과를 C의 u32 나눗셈과 대조합니다. 제수 경계, 2의 거듭제곱과 그 주변, 최대 피제수와 무작위 값을 포함해야 합니다.')])

    lesson('JIT 나눗셈·곱셈 계수의 상하 경계 줄이기', 'lib/math/reciprocal_div.c', 'reciprocal_value_adv',
        '실행할 기계어를 만들기 전에 더 많은 계산을 하여 생성 코드의 연산 수를 줄이는 기법을 배웁니다.',
        '고급 준비 함수는 l=ceil(log2(d))에서 mlow=floor(2^(32+l)/d), mhigh=floor((2^(32+l)+2^(32+l-prec))/d)를 만듭니다. 두 경계를 한 비트씩 줄여도 서로 다른 동안 mlow와 mhigh를 반감하고 post_shift를 줄입니다. 최종 mhigh의 낮은 32비트, 이동량 sh, 원래 지수 exp와 계수가 32비트를 넘는지 is_wide_m을 저장합니다.',
        '이 준비는 JIT 코드 생성처럼 준비 비용보다 반복 실행 코드를 줄이는 것이 유리할 때 사용합니다. 헤더의 정상 흐름은 먼저 큰 제수를 처리하고 전체 정밀도 32 또는 사전 이동 후의 정밀도를 전달합니다. 임의 prec나 제수 0의 유효성을 함수가 검사해 준다고 가정하지 않습니다.',
        'mlow·mhigh, lo>=hi 중단 조건과 post_shift 감소를 읽으세요.',
        [('두 반감된 경계 lo와 hi가 같아지면 왜 중단하는가?', '필요한 경계 차이를 더 이상 유지하지 못하기 때문이다', '제수 자체가 0으로 바뀌었기 때문이다', '루프는 lo>=hi이면 더 반감하지 않고 이전 유효 경계를 유지합니다. 제수는 루프 중 바뀌지 않습니다.'),
         ('고급 준비가 일반 호스트 나눗셈마다 유리하다고 볼 수 있는가?', '아니며 준비와 생성 코드의 비용을 구분해야 한다', '호출 횟수와 상관없이 항상 더 빠르다', '원본 헤더는 고급 준비의 복잡도가 일반 호스트 에뮬레이션의 절약을 상쇄할 수 있다고 설명하고 JIT 생성에 적합한 동기를 제시합니다.')],
        [('고급 구조체', 'reciprocal_value_adv의 m은 저장된 낮은 계수이고 sh는 최종 이동량, exp는 제수의 원래 지수입니다. is_wide_m이 참이면 단순 낮은 계수 곱만으로 계산하지 않습니다.'),
         ('큰 제수 경고', 'l==32이면 64비트 범위와 shift가 부족합니다. WARN은 진단이며 안전하게 오류 반환하는 분기가 아닙니다. 호출자가 헤더의 예외 처리로 그 입력을 피해야 합니다.')])

    lesson('JIT 나눗셈·큰 제수와 2의 거듭제곱 우회', 'include/linux/reciprocal_div.h', 'reciprocal_value_adv',
        '일반 곱셈 경로에 들어가기 전에 간단한 나눗셈을 안전하게 처리하는 조건을 배웁니다.',
        'u32 제수 d가 2^31 이상이면 u32 피제수 n의 몫은 0 또는 1이므로 n>=d로 계산합니다. 그보다 작은 양수 제수가 정확히 2^exp이면 n>>exp로 계산합니다. 이 두 우회는 고급 준비의 큰 shift 문제와 불필요한 곱셈을 피합니다. 제수 1도 exp=0 이동으로 처리합니다.',
        '헤더의 설명은 완성된 호출 함수가 아니라 코드 생성 의사코드입니다. imm은 실제 고정 제수에 연결해야 하고 1U<<exp의 유효 범위를 지켜야 합니다. 제수 0을 먼저 거절하고 예외 처리를 준비 함수보다 앞에 둡니다.',
        'd>=1U<<31의 먼저 반환과 imm 비교가 의미하는 상수를 읽으세요.',
        [('u32에서 d=2^31일 때 가능한 몫은?', '0 또는 1이다', '0부터 255까지다', 'u32 최대 피제수는 2^32-1이므로 d의 두 배보다 작습니다. n>=d인지 비교하면 몫이 결정됩니다.'),
         ('고정 제수 16의 나눗셈 생성 코드로 적절한 것은?', '부호 없는 n을 오른쪽으로 4비트 이동한다', '부호 없는 n을 왼쪽으로 4비트 이동한다', '16은 2^4이므로 부호 없는 정수 몫은 n>>4입니다. 왼쪽 이동은 곱셈 방향입니다.')],
        [('경계 포함', '원본 준비 경고는 ceil(log2(d))==32를 지적하지만 헤더의 호출 흐름은 d>=2^31을 먼저 처리합니다. 두 조건을 같은 문장으로 섞지 말고 실제 호출 예외 범위를 따릅니다.'),
         ('의사코드 초기값', '좁은 계수 분기의 result는 사전 이동이 없을 때도 n으로 초기화해야 합니다. 헤더 설명을 그대로 복사해 미초기화 result를 곱하는 실행 코드로 만들지 않습니다.')])

    lesson('JIT 나눗셈·넓은 계수의 차이 보정', 'include/linux/reciprocal_div.h', 'reciprocal_value_adv',
        '32비트보다 큰 계수의 낮은 부분을 저장하고 잃은 상위 정보를 보정하는 경로를 배웁니다.',
        'is_wide_m이 참이면 저장 m만 곱한 높은 절반 t를 얻습니다. n-t를 반감하고 t를 더한 뒤 sh-1만큼 이동해 몫을 만듭니다. 넓은 계수의 높은 비트를 단순히 버린 곱으로 대체하지 않고 차이 보정에 포함합니다. 2의 거듭제곱 우회를 먼저 수행해 sh-1이 유효한 경로에서 이 식을 사용합니다.',
        '헤더는 이 경로에서 pre_shift가 0이라고 설명합니다. 준비 구조의 is_wide_m을 보고 좁은 곱 경로와 분리하며 sh와 m만을 다른 제수에서 가져와 섞지 않습니다. 생성된 식을 원래 정수 몫과 대조합니다.',
        't 계산, n-t, 오른쪽 1비트 이동, t 더하기 순서를 읽으세요.',
        [('넓은 계수에서 m의 낮은 32비트 곱만 사용하면 충분한가?', '아니며 차이 보정과 이동이 필요하다', '항상 충분하므로 is_wide_m은 의미 없다', 'm은 넓은 준비 계수 전체를 저장하지 않습니다. 헤더의 넓은 경로는 그 표현을 보정하는 추가 연산을 제공합니다.'),
         ('넓은 계수 경로에서 마지막 이동량은?', 'sh-1이다', '무조건 exp+32다', '원본 의사코드는 차이를 먼저 한 비트 줄이고 t를 더한 뒤 sh-1을 사용합니다. 연산의 순서와 이동량을 함께 지켜야 합니다.')],
        [('반올림과 순서', '정수 오른쪽 이동은 낮은 비트를 버립니다. 덧셈·뺄셈과 이동을 실수식처럼 임의로 재배열하면 몫이 달라질 수 있습니다.'),
         ('원본 범위', '헤더는 준비 결과를 이용한 생성 코드의 흐름을 설명합니다. 실제 JIT의 명령 선택·레지스터 할당·기계어 실행은 이 두 파일만으로 구현되거나 검증되지 않습니다.')])

    lesson('JIT 나눗셈·짝수 제수의 사전 이동과 좁은 곱', 'include/linux/reciprocal_div.h', 'reciprocal_value_adv',
        '짝수 제수의 2 인수를 먼저 제거해 생성 코드의 넓은 계수 보정을 줄이는 방법을 배웁니다.',
        '첫 준비 결과가 넓고 d가 짝수이면 pre_shift=fls(d & -d)-1로 제수의 2 인수 지수를 얻습니다. d를 그만큼 이동하고 정밀도 32-pre_shift로 다시 준비합니다. 좁은 계수 경로에서는 피제수 n도 pre_shift만큼 이동한 뒤 m과 곱한 높은 절반을 sh만큼 이동합니다. 사전 이동이 없으면 n 자체를 곱의 입력으로 사용합니다.',
        '사전 이동은 아무 짝수 제수에 무조건 적용하는 별도 규칙이 아니라 원본의 넓은 계수 조건에서 사용하는 흐름입니다. exp는 처음 제수 기준으로 별도 보관하여 2의 거듭제곱 우회와 연결합니다. 입력 폭이 줄어든 만큼 재준비의 prec도 바뀝니다.',
        'd & -d, fls의 1부터 시작하는 결과, 재준비의 32-pre_shift를 읽으세요.',
        [('d=12에서 가장 낮은 1비트 4의 사전 이동량은?', '2다', '4다', 'fls(4)는 3이고 여기서는 1을 빼 2를 얻습니다. 12>>2=3이며 피제수도 같은 2 인수를 먼저 제거합니다.'),
         ('pre_shift가 0인 좁은 경로의 곱 입력은 무엇인가?', '원래 피제수 n이다', '초기화되지 않은 지역 변수다', '사전 이동이 없으면 result=n이어야 합니다. 설명 의사코드를 실행 코드로 옮길 때 이 초기값을 명시해야 합니다.')],
        [('정밀도 연결', '피제수를 미리 이동하면 사용되는 유효 비트 수가 줄어듭니다. 재준비의 prec=32-pre_shift는 이 입력 범위에 연결된 값이며 임의로 고르면 같은 몫 계약을 잃습니다.'),
         ('API 연결', 'lib/math/reciprocal_div.c는 두 준비 함수를 EXPORT_SYMBOL로 공개하고 헤더는 기본 계산 inline과 고급 생성 흐름을 제공합니다. 고급 계산용 별도 공개 inline 함수가 있다고 착각하지 않습니다.')])
